-- Classroom badges, round two: lesson planning and syllabus completion, and the
-- teacher ladder opened to coordinators.
--
-- APPLIED TO PROD 2026-09-07 10:50 IST via scripts/run-sql.ps1, after two edits to
-- this file: ORDER BY tb.id on both upserts (deadlock order) and the UPDATE
-- trigger's column list removed (0A000). Runbook §5 checks all green; backfill
-- awarded 54 badges to 31 staff. Do not edit this file again; write a new one.
--
-- >>> APPLYING THIS? Read docs/superpowers/plans/2026-09-04-classroom-badges-db-rollout.md
-- >>> first. It has the preconditions to verify, the measurement step that
-- >>> re-paces the provisional rungs in §1, the post-apply checks, the smoke
-- >>> test, the frontend ship order, and a rollback. The SQL below was written
-- >>> without prod access.
--
-- WHAT THIS ADDS. Two metrics to evaluate_teacher_badges() and six catalog rows
-- under category 'classroom':
--   * lessons_planned_ahead      a tt_lesson_plans row whose planned_at, read as
--                                the institution's local date, is EARLIER than
--                                the period date. The teacher-side answer to
--                                "reward timetable creation": the timetable grid
--                                is an admin write (tt_class_structure / tt_slots
--                                are admin-only RLS), but planning the lesson
--                                that fills a period is the teacher's own work.
--   * syllabus_topics_completed  DISTINCT syllabus_progress_events.topic_id with
--                                action = 'completed', recorded by the teacher.
--
-- WHY COORDINATORS. The 20260818120000 guard admitted only user_roles.role =
-- 'teacher', so a coordinator-only user who marks attendance, plans lessons and
-- completes chapters collected nothing, and the page sent them to a legacy grid
-- of four 'coordinator' rows (three on tasks_completed, one on the never-computed
-- tasks_on_time). Coordinators teach; they join the one ladder. The four legacy
-- rows are deactivated (holders keep their awards and points), and the frontend
-- routes both roles to the teacher surface in the same change.
--
-- PRECONDITIONS (verify in prod, the ledger is not maintained):
--   * tt_lesson_plans.is_note_only exists (20260902120000). The trigger WHEN
--     clauses below reference it and CREATE TRIGGER fails loudly if it is absent,
--     which is the right failure.
--   * The live evaluate_teacher_badges body carries the 20260902120000 in-place
--     patch (AND lp.session_type = 'teaching'). This file re-emits the WHOLE body
--     and includes that clause. Diff pg_get_functiondef against this text before
--     applying so no other in-place patch is silently reverted. Query 4 of
--     scripts/measure-classroom-badge-ladders.sql does the check.
--
-- RUNGS ARE PROVISIONAL. The 20260818120000 ladders were paced against measured
-- per-teacher distributions; these were written without prod access. Run
-- scripts/measure-classroom-badge-ladders.sql first and re-pace the CTE in §1 so
-- bronze is reachable on day one and gold is a real summit. The catalog CTE
-- re-asserts criteria_value on re-run, so re-pacing later is one UPDATE away.

-- ── 1. Catalog ──────────────────────────────────────────────────────────────
-- Same shape as 20260818120000 §3: one CTE feeds INSERT-where-missing and the
-- re-assert UPDATE, so the two cannot drift. is_active is excluded from the
-- re-assert. icon_name values are keys already used by the live seed, so
-- src/components/badges/BadgeIcon.tsx needs no change.
--
-- display_order only orders tiles WITHIN a tab (tabs filter on category), so
-- 220 / 221 here colliding with the assessment band is harmless. The band
-- comment in teacherCategories.ts is updated to classroom 210-221.
WITH cat (name, description, icon_name, category, tier,
          criteria_metric, criteria_value, points, display_order) AS (
  VALUES
    -- planning ahead. PROVISIONAL, see header.
    ('Planned Ahead',       'Plan a lesson before the day it is taught', 'calendar-check',  'classroom', 'bronze', 'lessons_planned_ahead',      1, 10, 216),
    ('Week Ready',          'Plan 10 lessons ahead of time',             'clipboard-check', 'classroom', 'silver', 'lessons_planned_ahead',     10, 30, 217),
    ('Term Ready',          'Plan 40 lessons ahead of time',             'compass',         'classroom', 'gold',   'lessons_planned_ahead',     40, 80, 218),
    -- chapters completed. PROVISIONAL, see header. "Chapter" is the word the
    -- syllabus UI uses for a syllabus_topics row.
    ('Topic Ticked',        'Mark your first chapter as completed',      'check-circle',    'classroom', 'bronze', 'syllabus_topics_completed',  1, 10, 219),
    ('Chapter Closer',      'Complete 10 chapters',                      'book-open',       'classroom', 'silver', 'syllabus_topics_completed', 10, 35, 220),
    ('Curriculum Complete', 'Complete 40 chapters',                      'target',          'classroom', 'gold',   'syllabus_topics_completed', 40, 90, 221)
),
ins AS (
  INSERT INTO badge_definitions
    (name, description, icon_name, badge_type, category, tier,
     criteria_type, criteria_metric, criteria_value, points, is_active, display_order)
  SELECT c.name, c.description, c.icon_name, 'teacher', c.category, c.tier,
         'count', c.criteria_metric, c.criteria_value, c.points, true, c.display_order
  FROM cat c
  WHERE NOT EXISTS (
    SELECT 1 FROM badge_definitions bd
    WHERE bd.badge_type = 'teacher' AND bd.name = c.name
  )
  RETURNING id
)
UPDATE badge_definitions bd
SET description = c.description, icon_name = c.icon_name, category = c.category,
    tier = c.tier, criteria_type = 'count', criteria_metric = c.criteria_metric,
    criteria_value = c.criteria_value, points = c.points,
    display_order = c.display_order, updated_at = now()
FROM cat c
WHERE bd.badge_type = 'teacher' AND bd.name = c.name
  AND (bd.description, bd.icon_name, bd.category, bd.tier, bd.criteria_type,
       bd.criteria_metric, bd.criteria_value, bd.points, bd.display_order)
      IS DISTINCT FROM
      (c.description, c.icon_name, c.category, c.tier, 'count',
       c.criteria_metric, c.criteria_value, c.points, c.display_order);

-- ── 2. Retire the legacy coordinator catalog ────────────────────────────────
-- Rows kept, not deleted: holders keep the award and the points (nothing that
-- sums points filters on is_active). Deactivating is what stops the browser-side
-- awarder (useAutoBadgeAward, which reads is_active rows with badge_type <>
-- 'teacher') from handing coordinators a second tasks_completed ladder now that
-- they are on the teacher one.
UPDATE badge_definitions bd
SET is_active = false, updated_at = now()
WHERE bd.badge_type = 'coordinator' AND bd.is_active;

-- ── 3. Supporting index ─────────────────────────────────────────────────────
-- lessons_planned_ahead probes tt_lesson_plans by owner with four constant
-- predicates. idx_tt_lesson_plans_owner_date (owner_teacher_id, date) would
-- serve it, but a partial index over exactly the rows that can count keeps the
-- probe to the planned-with-a-chapter subset, which is a fraction of the table
-- once check-in rows and note-only rows are excluded. The date comparison needs
-- the institutions join and stays a per-row filter.
--
-- syllabus_topics_completed rides spe_recorded_by_idx (recorded_by), created
-- with the table in 20260704140000.
--
-- Plain CREATE INDEX: a migration runs in a transaction and CONCURRENTLY is not
-- allowed there. Brief write lock on tt_lesson_plans; apply outside school hours.
CREATE INDEX IF NOT EXISTS idx_tt_lesson_plans_owner_planned
  ON public.tt_lesson_plans (owner_teacher_id)
  WHERE planned_at IS NOT NULL
    AND session_type = 'teaching'
    AND NOT is_note_only
    AND topic_id IS NOT NULL;

-- ── 4. The evaluator ────────────────────────────────────────────────────────
-- Full re-emit of the live body (20260818120000 §5 + the 20260902120000 patch)
-- with: the widened role guard, two new counters, two new rows in the metrics
-- tuple, and both counters in the early return. Everything else is unchanged.
--
-- §24 NOTE. lessons_planned_ahead is the first metric in this function that
-- compares a timestamp to a calendar date. planned_at is a timestamptz stamped
-- with now() by tt_lesson_plans_stamp_status; lp.date is the institution's local
-- calendar date. The comparison converts planned_at with the institution's own
-- timezone (institutions.timezone, default Asia/Kolkata), never UTC: a lesson
-- planned at 23:30 IST for the next day is planned ahead, and reading it in UTC
-- (18:00 the same day) happens to agree, but a lesson planned at 02:00 IST for
-- the same day would read as the previous UTC date and be wrongly counted.
CREATE OR REPLACE FUNCTION public.evaluate_teacher_badges(
  _user_id uuid,
  _notify  boolean DEFAULT true
)
RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_inst       uuid;
  v_attendance int := 0;
  v_lessons    int := 0;
  v_exams      int := 0;
  v_answers    int := 0;
  v_hw_created int := 0;
  v_hw_marked  int := 0;
  v_tasks      int := 0;
  v_planned    int := 0;
  v_topics     int := 0;
  v_new_ids    uuid[] := ARRAY[]::uuid[];
BEGIN
  IF _user_id IS NULL THEN RETURN 0; END IF;

  -- These are badge_type = 'teacher'. Teachers and coordinators both teach and
  -- share one ladder; admins also create exams and mark attendance and should
  -- not collect it. user_roles is the authority, and holding either qualifying
  -- role alongside another one qualifies.
  IF NOT EXISTS (
    SELECT 1 FROM user_roles ur
    WHERE ur.user_id = _user_id AND ur.role IN ('teacher', 'coordinator')
  ) THEN
    RETURN 0;
  END IF;

  -- DISTINCT DATES, not rows. Marking one class of 40 students is one day of
  -- work, not 40; counting rows would hand out Never Misses on the first save.
  SELECT count(DISTINCT ar.date)::int INTO v_attendance
  FROM attendance_records ar
  WHERE ar.marked_by = _user_id;

  -- 'Lessons taught' means chapter delivery. A logged surprise test is real work
  -- but it is not a lesson (20260902120000).
  SELECT count(*)::int INTO v_lessons
  FROM tt_lesson_plans lp
  WHERE lp.owner_teacher_id = _user_id AND lp.status = 'done'
    AND lp.session_type = 'teaching';

  -- No status filter: the metric is exams CREATED. A paper that was written and
  -- then never published is still a paper the teacher wrote, and the AFTER
  -- INSERT trigger below fires at exactly the moment this count moves.
  SELECT count(*)::int INTO v_exams
  FROM exams e
  WHERE e.created_by = _user_id;

  -- evaluated_by, NOT teacher_id. teacher_overrides has no teacher_id column;
  -- querying one is what made this metric read 0 for every teacher for months.
  --
  -- accepted_ai_suggestion = false is the "a human made the marking decision"
  -- test, and it is NOT the same as is_auto_graded = false. Measured over all
  -- 7,755 override rows in prod on 2026-08-18:
  --   auto=t acc=t  6,980  auto-grade-submission wrote the mark        -> machine
  --   auto=f acc=f    647  teacher marked from scratch                 -> human
  --   auto=f acc=t    110  teacher bulk-pressed "accept AI suggestion" -> machine
  --   auto=t acc=f     18  AI marked it, teacher then overrode it      -> human
  -- Filtering on is_auto_graded would keep the 110 button-presses and discard
  -- the 18 genuine corrections. 90% of this table is the model's work: counting
  -- it would have handed platinum "Marking Machine" to teachers who hand-marked
  -- nothing. Badges are irreversible here, so this errs toward under-counting.
  SELECT count(*)::int INTO v_answers
  FROM teacher_overrides t
  WHERE t.evaluated_by = _user_id
    AND NOT COALESCE(t.accepted_ai_suggestion, false);

  -- homework_assignments, not "homework": there is no table by that name.
  SELECT count(*)::int INTO v_hw_created
  FROM homework_assignments h
  WHERE h.created_by = _user_id;

  SELECT count(*)::int INTO v_hw_marked
  FROM homework_assignments h
  WHERE h.evaluated_by = _user_id;

  -- 'completed' is the only done state in prod. done_pending_approval is still
  -- waiting on someone else, so it is not the teacher's task finished yet.
  -- Multi-assignee work is FAN-OUT (N tasks rows sharing task_group_id, one
  -- assignment row each), so counting assignment rows counts people correctly.
  SELECT count(*)::int INTO v_tasks
  FROM task_assignments ta
  JOIN tasks tk ON tk.id = ta.task_id
  WHERE ta.assignee_id = _user_id AND tk.status = 'completed';

  -- Planned ahead. planned_at is stamped once, when the row first becomes
  -- 'planned' (tt_lesson_plans_stamp_status), and never moved afterwards, so a
  -- row that was planned on Monday for Wednesday still counts after it is
  -- taught, and a past lesson logged straight to 'done' (planned_at = now(),
  -- on or after the period date) never does. Chapter required: a row with no
  -- topic is a placeholder, not a plan. Note-only rows are activity logs.
  SELECT count(*)::int INTO v_planned
  FROM tt_lesson_plans lp
  JOIN institutions i ON i.id = lp.institution_id
  WHERE lp.owner_teacher_id = _user_id
    AND lp.planned_at IS NOT NULL
    AND (lp.planned_at AT TIME ZONE i.timezone)::date < lp.date
    AND lp.session_type = 'teaching'
    AND NOT lp.is_note_only
    AND lp.topic_id IS NOT NULL;

  -- DISTINCT chapters, not rows: the same chapter completed for two sections is
  -- one chapter taught twice. Every source counts, including the 'correction'
  -- rows the 20260704140000 backfill wrote from historical done lessons; they
  -- are the teacher's real teaching history, not corrections in the UI sense.
  SELECT count(DISTINCT e.topic_id)::int INTO v_topics
  FROM syllabus_progress_events e
  WHERE e.recorded_by = _user_id AND e.action = 'completed';

  IF GREATEST(v_attendance, v_lessons, v_exams, v_answers,
              v_hw_created, v_hw_marked, v_tasks, v_planned, v_topics) = 0 THEN
    RETURN 0;
  END IF;

  SELECT p.institution_id INTO v_inst FROM profiles p WHERE p.id = _user_id;

  -- Awards and progress in ONE statement off one metrics tuple, so the two can
  -- never disagree about what the teacher's numbers are. Both CTEs are
  -- data-modifying and therefore both execute, whether or not the outer query
  -- references them.
  WITH m (metric, val) AS (
    VALUES ('attendance_days_marked'::text,  v_attendance),
           ('lessons_taught',                v_lessons),
           ('exams_created',                 v_exams),
           ('answers_evaluated',             v_answers),
           ('homework_created',              v_hw_created),
           ('homework_marked',               v_hw_marked),
           ('tasks_completed',               v_tasks),
           ('lessons_planned_ahead',         v_planned),
           ('syllabus_topics_completed',     v_topics)
  ),
  tb AS (
    SELECT bd.id, bd.criteria_metric, bd.criteria_value, m.val
    FROM badge_definitions bd
    JOIN m ON m.metric = bd.criteria_metric
    WHERE bd.is_active AND bd.badge_type = 'teacher'
  ),
  ins AS (
    INSERT INTO user_badges
      (user_id, badge_id, institution_id, source_entity_type, metadata)
    SELECT _user_id, tb.id, v_inst, tb.criteria_metric,
           jsonb_build_object('count', tb.val)
    FROM tb
    WHERE tb.val >= tb.criteria_value
    -- Deterministic lock order: two evaluator runs for the SAME teacher (an
    -- attendance save in one tab, a lesson-plan save in another) upsert the
    -- same rows; without ORDER BY the join may emit them in different orders
    -- and the two sessions can deadlock, which the trigger wrapper would then
    -- swallow as a WARNING and the badge would silently not be awarded.
    ORDER BY tb.id
    -- Bare DO NOTHING: the guard is the expression index
    -- user_badges_once_per_period_idx (user_id, badge_id, COALESCE(period_key,'')),
    -- which cannot be named as a conflict target by column list.
    ON CONFLICT DO NOTHING
    RETURNING id
  ),
  prog AS (
    INSERT INTO badge_progress
      (user_id, badge_id, institution_id, current_value, target_value, last_updated)
    -- Every rung, earned or not, so an unearned tile reads "10 of 25" instead of
    -- a bar frozen at zero.
    SELECT _user_id, tb.id, v_inst, tb.val, tb.criteria_value, now()
    FROM tb
    ORDER BY tb.id   -- same lock-order reason as the awards insert above
    ON CONFLICT (user_id, badge_id) DO UPDATE
      SET current_value  = EXCLUDED.current_value,
          target_value   = EXCLUDED.target_value,
          institution_id = EXCLUDED.institution_id,
          last_updated   = now()
    RETURNING 1
  )
  SELECT COALESCE(array_agg(id), ARRAY[]::uuid[]) INTO v_new_ids FROM ins;

  -- Notifications in their OWN subtransaction, AFTER the award has landed. When
  -- these shared a statement with the award, a notifications failure rolled the
  -- award back with it, so the notification path could revoke a badge.
  IF _notify AND array_length(v_new_ids, 1) IS NOT NULL THEN
    BEGIN
      INSERT INTO notifications (user_id, type, title, message, link, metadata)
      SELECT ub.user_id, 'badge_earned',
             'Badge earned: ' || bd.name,
             'You earned the "' || bd.name || '" badge (+' || bd.points || ' points).',
             '/achievements',
             jsonb_build_object('badge_id', bd.id, 'badge_name', bd.name, 'points', bd.points)
      FROM user_badges ub
      JOIN badge_definitions bd ON bd.id = ub.badge_id
      WHERE ub.id = ANY (v_new_ids);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'evaluate_teacher_badges: awards committed, notifications failed: %', SQLERRM;
    END;
  END IF;

  RETURN COALESCE(array_length(v_new_ids, 1), 0);
END $$;

-- ── 5. Triggers ─────────────────────────────────────────────────────────────
-- trg_zz_* naming and the BEGIN / EXCEPTION WHEN OTHERS / RAISE WARNING wrap,
-- for the reasons in 20260818120000 §6: fire after audit rows, and never let a
-- badge fault roll back the teacher's own write.

-- 5a. tt_lesson_plans, planning side. The existing lesson triggers fire only on
--     the transition into 'done'; a plan saved for a future period never reached
--     the evaluator. Two triggers, reusing tg_zz_teacher_badges_lesson(), which
--     just evaluates NEW.owner_teacher_id.
--
--     Row-level is right here: useUpsertLessonPlan writes one row per save
--     (PostgREST upsert on slot_id, date), so one save is one evaluator call.
--
--     The UPDATE half guards on what can actually move the count. PostgREST's
--     upsert re-sends status = 'planned' on every edit of an existing plan, and
--     "UPDATE OF status" fires whenever the column is in the SET list, changed
--     or not; without the OLD comparison every note edit would run nine
--     aggregates for nothing. Three transitions matter: pending/skipped ->
--     planned, a first planned_at stamp, and a chapter added to a chapterless
--     plan. delete_syllabus_progress reverting done -> planned also fires it;
--     planned_at is untouched by that revert so the count does not move, and
--     one evaluator run per correction is an acceptable price.
--
--     The date comparison cannot live in WHEN (it needs the institutions join
--     for the timezone); the evaluator does it. A plan saved for today fires
--     the trigger, is counted as not-ahead, and moves nothing.
DROP TRIGGER IF EXISTS trg_zz_teacher_badges_lesson_planned ON public.tt_lesson_plans;
CREATE TRIGGER trg_zz_teacher_badges_lesson_planned
AFTER INSERT ON public.tt_lesson_plans
FOR EACH ROW WHEN (NEW.status = 'planned'
                   AND NEW.owner_teacher_id IS NOT NULL
                   AND NEW.planned_at IS NOT NULL
                   AND NOT NEW.is_note_only
                   AND NEW.topic_id IS NOT NULL)
EXECUTE FUNCTION public.tg_zz_teacher_badges_lesson();

DROP TRIGGER IF EXISTS trg_zz_teacher_badges_lesson_planned_upd ON public.tt_lesson_plans;
CREATE TRIGGER trg_zz_teacher_badges_lesson_planned_upd
AFTER UPDATE OF status, planned_at, topic_id ON public.tt_lesson_plans
FOR EACH ROW WHEN (NEW.status = 'planned'
                   AND NEW.owner_teacher_id IS NOT NULL
                   AND NEW.planned_at IS NOT NULL
                   AND NOT NEW.is_note_only
                   AND NEW.topic_id IS NOT NULL
                   AND (OLD.status IS DISTINCT FROM 'planned'
                        OR OLD.planned_at IS NULL
                        OR OLD.topic_id IS NULL))
EXECUTE FUNCTION public.tg_zz_teacher_badges_lesson();

-- 5b. syllabus_progress_events. Statement-level with a transition table, same
--     shape as the teacher_overrides pair: record_syllabus_progress is the
--     single write path and upserts one row per call, so this is one evaluator
--     run per check-in, and a future bulk correction still collapses to one run
--     per recorder. The UPDATE half catches partial -> completed on the same
--     (class, subject, chapter, date) key, which the upsert's DO UPDATE writes.
CREATE OR REPLACE FUNCTION public.tg_zz_teacher_badges_syllabus()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r record;
BEGIN
  BEGIN
    FOR r IN
      SELECT DISTINCT n.recorded_by AS teacher_id
      FROM newrows n
      WHERE n.recorded_by IS NOT NULL AND n.action = 'completed'
    LOOP
      PERFORM public.evaluate_teacher_badges(r.teacher_id);
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'tg_zz_teacher_badges_syllabus failed: %', SQLERRM;
  END;
  RETURN NULL;
END $$;

DROP TRIGGER IF EXISTS trg_zz_teacher_badges_syllabus ON public.syllabus_progress_events;
CREATE TRIGGER trg_zz_teacher_badges_syllabus
AFTER INSERT ON public.syllabus_progress_events
REFERENCING NEW TABLE AS newrows
FOR EACH STATEMENT
EXECUTE FUNCTION public.tg_zz_teacher_badges_syllabus();

-- No column list here on purpose: Postgres refuses "UPDATE OF col ...
-- REFERENCING NEW TABLE" (SQLSTATE 0A000, "transition tables cannot be
-- specified for triggers with column lists"), which is exactly how the first
-- apply of this file failed on 2026-09-07. The function filters the transition
-- table on action = 'completed', so an unrelated UPDATE of this small table
-- costs one evaluator run and awards nothing new.
DROP TRIGGER IF EXISTS trg_zz_teacher_badges_syllabus_upd ON public.syllabus_progress_events;
CREATE TRIGGER trg_zz_teacher_badges_syllabus_upd
AFTER UPDATE ON public.syllabus_progress_events
REFERENCING NEW TABLE AS newrows
FOR EACH STATEMENT
EXECUTE FUNCTION public.tg_zz_teacher_badges_syllabus();

-- ── 6. Backfill ─────────────────────────────────────────────────────────────
-- Two groups earn retroactively here: every teacher, for the two new metrics,
-- and every coordinator-only user, for the whole ladder they were locked out
-- of. One loop covers both. Re-running the evaluator for a teacher who was
-- backfilled in 20260818120000 is idempotent (ON CONFLICT DO NOTHING on awards,
-- upsert on progress), so the pre-filter is only there to skip users with no
-- activity at all. _notify = false, one summary notification per user, and the
-- copy stays generic because for a coordinator this may be their first badge.
DO $$
DECLARE r record; v_total int := 0; v_seen int := 0; v_n int := 0;
BEGIN
  FOR r IN
    SELECT DISTINCT ur.user_id AS id
    FROM user_roles ur
    WHERE ur.role IN ('teacher', 'coordinator')
      AND (
           EXISTS (SELECT 1 FROM exams e                WHERE e.created_by = ur.user_id)
        OR EXISTS (SELECT 1 FROM homework_assignments h WHERE h.created_by = ur.user_id)
        OR EXISTS (SELECT 1 FROM homework_assignments h WHERE h.evaluated_by = ur.user_id)
        OR EXISTS (SELECT 1 FROM teacher_overrides t    WHERE t.evaluated_by = ur.user_id
                                                          AND NOT COALESCE(t.accepted_ai_suggestion, false))
        OR EXISTS (SELECT 1 FROM tt_lesson_plans lp     WHERE lp.owner_teacher_id = ur.user_id
                                                          AND lp.status = 'done'
                                                          AND lp.session_type = 'teaching')
        OR EXISTS (SELECT 1 FROM tt_lesson_plans lp     WHERE lp.owner_teacher_id = ur.user_id
                                                          AND lp.planned_at IS NOT NULL
                                                          AND lp.session_type = 'teaching'
                                                          AND NOT lp.is_note_only
                                                          AND lp.topic_id IS NOT NULL)
        OR EXISTS (SELECT 1 FROM syllabus_progress_events e WHERE e.recorded_by = ur.user_id
                                                              AND e.action = 'completed')
        OR EXISTS (SELECT 1 FROM attendance_records ar  WHERE ar.marked_by = ur.user_id)
        OR EXISTS (SELECT 1 FROM task_assignments ta
                   JOIN tasks tk ON tk.id = ta.task_id
                   WHERE ta.assignee_id = ur.user_id AND tk.status = 'completed')
      )
  LOOP
    v_seen  := v_seen + 1;
    v_n     := public.evaluate_teacher_badges(r.id, false);
    v_total := v_total + v_n;

    IF v_n > 0 THEN
      BEGIN
        INSERT INTO notifications (user_id, type, title, message, link, metadata)
        VALUES (
          r.id, 'badge_earned',
          'You have ' || v_n || CASE WHEN v_n = 1 THEN ' new teaching badge'
                                     ELSE ' new teaching badges' END,
          'Your teaching work so far has been recognised. Open Achievements to see '
            || CASE WHEN v_n = 1 THEN 'it.' ELSE 'them.' END,
          '/achievements',
          jsonb_build_object('backfill', true, 'awarded', v_n)
        );
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'classroom badge backfill: awards committed, summary notification failed for %: %', r.id, SQLERRM;
      END;
    END IF;
  END LOOP;
  RAISE NOTICE 'classroom badge backfill: % users evaluated, % badges awarded', v_seen, v_total;
END $$;

-- ── 7. Grants ───────────────────────────────────────────────────────────────
-- FROM PUBLIC first, then the roles by name (Supabase's default privileges
-- grant EXECUTE to PUBLIC on every new public function; see 20260818120000 §8).
-- CREATE OR REPLACE keeps the evaluator's existing ACL, but it is re-asserted so
-- a fresh database gets the same result. Verify with pg_proc.proacl: no leading
-- '=X/' entry.
REVOKE ALL ON FUNCTION public.evaluate_teacher_badges(uuid, boolean) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.tg_zz_teacher_badges_syllabus()        FROM PUBLIC, anon, authenticated;
